def solve(nA, nB, d):
    f = []
    for a in range(-d, nB + d):
        val = min(nB - 1, a + d) - max(0, a - d) + 1
        if val > 0:
            f.append(val)
    f.sort(reverse=True)
    return sum(f[:nA])

nA = 2000
nB = 2016
d = 1000
print(solve(nA, nB, d))

def solve_block(nA, nB, d):
    A = list(range(1, nA + 1))
    B = list(range(1001, 1001 + nB))
    K = 0
    for a in A:
        for b in B:
            if abs(a - b) <= d:
                K += 1
    return K

print(solve_block(2000, 2016, 1000))

